"""BL-110 Amendment 1: the same persistence questions on |close-to-close| returns from Momentum's
daily NIFTY file (open and close only), 2016 to 2026. The rule is the item's Amendment 1.

    uv run python research/bl110/proxy_2016.py
"""

from __future__ import annotations

import csv
import json
from datetime import date
from pathlib import Path

import numpy as np

# Momentum's daily NIFTY file (date, open, close; gitignored, regenerated by `mbt fetch`)
SRC = Path(__file__).resolve().parents[4] / "packages/momentum-backtesting/data/daily/Nifty 50.csv"
OUT = Path(__file__).parent
LOOKBACK, EXPANDED, RANGEBOUND = 20, 1.25, 0.80
BLOCK, RESAMPLES, SEED, LEVEL = 20, 2000, 20261015, 0.90
CONFIRM = (date(2016, 2, 1), date(2021, 12, 31))
BRIDGE = (date(2022, 1, 3), date(2026, 10, 9))


def ranks(x):
    _, inv, counts = np.unique(x, return_inverse=True, return_counts=True)
    return (np.cumsum(counts) - (counts - 1) / 2)[inv]


def spearman(x, y):
    return float(np.corrcoef(ranks(x), ranks(y))[0, 1]) if len(x) > 4 else float("nan")


def interval(stat, n, offset=0):
    rng = np.random.default_rng(SEED + offset)
    nb = -(-n // BLOCK)
    starts = rng.integers(0, n, size=(RESAMPLES, nb))
    idx = ((starts[:, :, None] + np.arange(BLOCK)[None, None, :]) % n).reshape(RESAMPLES, -1)[:, :n]
    vals = np.array([stat(i) for i in idx])
    vals = vals[np.isfinite(vals)]
    return [float(v) for v in np.percentile(vals, [(1 - LEVEL) / 2 * 100, (1 + LEVEL) / 2 * 100])]


def load():
    days, close = [], []
    with SRC.open() as f:
        for r in csv.DictReader(f):
            days.append(date.fromisoformat(r["date"]))
            close.append(float(r["close"]))
    c = np.array(close)
    m = np.abs(np.diff(np.log(c))) * 100  # M_t for t = 1..n-1
    return np.array(days[1:]), m


def analyse(day, m, lo, hi):
    n = len(m)
    base = np.full(n, np.nan)
    for t in range(LOOKBACK, n):
        base[t] = np.median(m[t - LOOKBACK : t])
    inside = np.array([lo <= d <= hi for d in day])
    ok = inside & np.isfinite(base) & (base > 0)
    e = np.where(ok, m / np.where(base > 0, base, np.nan), np.nan)
    state = np.where(e >= EXPANDED, 1, np.where(e <= RANGEBOUND, -1, 0))
    logm = np.log(np.maximum(m, 1e-4))
    t1 = np.array([i for i in range(n - 1) if ok[i]])
    ac = {
        "rho": spearman(logm[t1], logm[t1 + 1]),
        "ci90": interval(lambda i: spearman(logm[t1][i], logm[t1 + 1][i]), len(t1), 1),
        "n": int(len(t1)),
    }
    f1 = m[t1 + 1] / base[t1]
    s = state[t1]

    def gap(i):
        a, b = s[i] == 1, s[i] == -1
        return f1[i][a].mean() - f1[i][b].mean() if a.any() and b.any() else np.nan

    out = {
        "autocorrelation_log_abs_return_lag1": ac,
        "expanded": {
            "n": int((s == 1).sum()),
            "mean_f1": float(f1[s == 1].mean()),
            "p_next_expanded": float((state[t1 + 1][s == 1] == 1).mean()),
        },
        "range_bound": {
            "n": int((s == -1).sum()),
            "mean_f1": float(f1[s == -1].mean()),
            "p_next_range_bound": float((state[t1 + 1][s == -1] == -1).mean()),
        },
        "p_expanded_overall": float((s == 1).mean()),
        "p_range_bound_overall": float((s == -1).mean()),
        "f1_expanded_minus_range_bound": {
            "diff": float(f1[s == 1].mean() - f1[s == -1].mean()),
            "ci90": interval(gap, len(t1), 2),
        },
    }
    return out


def main():
    day, m = load()
    report = {
        "source": str(SRC),
        "sessions": int(len(m)),
        "confirm_2016_2021": analyse(day, m, *CONFIRM),
        "bridge_2022_2026": analyse(day, m, *BRIDGE),
    }
    c = report["confirm_2016_2021"]
    report["verdict"] = {
        "supported": c["autocorrelation_log_abs_return_lag1"]["ci90"][0] > 0
        and c["f1_expanded_minus_range_bound"]["ci90"][0] > 0
    }
    (OUT / "proxy_2016_2026-10-15.json").write_text(json.dumps(report, indent=1) + "\n")
    print(json.dumps(report, indent=1))


if __name__ == "__main__":
    main()
